export default async function handler(req, res) {
  setCors(req, res, "GET, POST, OPTIONS");
  if (req.method === "OPTIONS") return res.status(200).end();
  if (req.method !== "POST") return res.status(405).json({ error: "POST only" });

  try {
    const pool = getPool();
    let updated = 0, skipped = 0, errors = 0;
    const errs = [];

    for (const row of UPDATES) {
      try {
        const r = await pool.query(`
          UPDATE products SET
            cbm          = COALESCE(cbm,          $1::numeric),
            net_weight   = COALESCE(net_weight,   $2::numeric),
            gross_weight = COALESCE(gross_weight, $3::numeric),
            carton_qty   = COALESCE(carton_qty,   $4::int),
            barcode      = COALESCE(NULLIF(barcode,''), $5),
            spec_source  = COALESCE(spec_source,  'factory_spec'),
            spec_verified      = CASE WHEN spec_source IS NULL THEN TRUE ELSE spec_verified END,
            spec_verified_at   = CASE WHEN spec_source IS NULL THEN NOW() ELSE spec_verified_at END,
            spec_verified_by   = CASE WHEN spec_source IS NULL
                                  THEN 'product_info_xlsx_2026-05-20'
                                  ELSE spec_verified_by END
          WHERE sku = $6
        `, [row.cbm, row.net_weight, row.gross_weight,
            row.carton_qty, row.barcode, row.sku]);

        if (r.rowCount > 0) updated++;
        else skipped++;
      } catch (e) {
        errors++;
        if (errs.length < 10) errs.push({ sku: row.sku, error: e.message });
      }
    }

    const verify = await pool.query(`
      SELECT
        COUNT(*) FILTER (WHERE spec_source = 'factory_spec') AS factory_spec,
        COUNT(*) FILTER (WHERE spec_source = 'trade_show')   AS trade_show,
        COUNT(*) FILTER (WHERE spec_source IS NULL)          AS unsourced,
        COUNT(*) FILTER (WHERE carton_qty IS NOT NULL)       AS has_carton_qty,
        COUNT(*) FILTER (WHERE cbm IS NOT NULL)              AS has_cbm,
        COUNT(*) FILTER (WHERE spec_verified = TRUE)         AS verified,
        COUNT(*) AS total
      FROM products
    `);

    return res.status(200).json({
      migration: "migrate-products-cp-backfill",
      date: "2026-05-20",
      input_rows: UPDATES.length,
      updated, skipped, errors,
      sample_errors: errs,
      verification: verify.rows[0],
      ok: errors === 0,
    });
  } catch (err) {
    return res.status(500).json({ error: err.message, stack: err.stack });
  }
}
